discrete ArmControlSystem
port:
    event input real ReceiveTaskCommand;
    event output real TaskCompleted;
state:
    initial state Idle
        when entry() then
            statehold(5);
        end;
        when receive(ReceiveTaskCommand) then
            transition(Working);
        end;
    end;

    state Working
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(Idle);
            out
                send(TaskCompleted, 1);
            end;
        end;
    end;
end;
end;

discrete SensorSystem
port:
    event input real ValueExceedsThreshold;
    event output real WarningTriggered;
    event output real ErrorDetected;
state:
    initial state Normal
        when entry() then
            statehold(5);
        end;
        when receive(ValueExceedsThreshold) then
            transition(Warning);
        end;
    end;

    state Warning
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(Error);
            out
                send(ErrorDetected, 1);
        end;
    end;

    state Error
        when entry() then
            statehold(5);
        end;
        when receive(ValueExceedsThreshold) then
            transition(Normal);
            out
                send(WarningTriggered, 1);
        end;
    end;
end;
end;

discrete TaskScheduler
port:
    event input real NewTaskReceived;
    event output real SchedulingCompleted;
    event output real ExecutionCompleted;
state:
    initial state Ready
        when entry() then
            statehold(5);
        end;
        when receive(NewTaskReceived) then
            transition(Scheduling);
        end;
    end;

    state Scheduling
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(Executing);
            out
                send(SchedulingCompleted, 1);
        end;
    end;

    state Executing
        when entry() then
            statehold(15);
        end;
        when timeover() then
            transition(Completed);
            out
                send(ExecutionCompleted, 1);
        end;
    end;

    state Completed
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(Ready);
        end;
    end;
end;
end;

discrete SafetyMonitor
port:
    event input real RiskDetected;
    event output real AlertTriggered;
    event output real ShutdownInitiated;
state:
    initial state Safe
        when entry() then
            statehold(5);
        end;
        when receive(RiskDetected) then
            transition(Alert);
        end;
    end;

    state Alert
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(Shutdown);
            out
                send(ShutdownInitiated, 1);
        end;
    end;

    state Shutdown
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(Safe);
            out
                send(AlertTriggered, 1);
        end;
    end;
end;
end;

couple IndustrialRobotSystem
import architectureModels.ArmControlSystem as ArmCtrl;
import architectureModels.SensorSystem as SenSys;
import architectureModels.TaskScheduler as TskSch;
import architectureModels.SafetyMonitor as SafMon;

part:
    ArmCtrl ArmControlInstance;
    SenSys SensorSystemInstance;
    TskSch TaskSchedulerInstance;
    SafMon SafetyMonitorInstance;

connection:
    connect(TaskSchedulerInstance.TaskAssigned, ArmControlInstance.ReceiveTaskCommand);
    connect(ArmControlInstance.TaskCompleted, TaskSchedulerInstance.TaskReceived);
    connect(SensorSystemInstance.SensorData, SafetyMonitorInstance.RiskDetected);
    connect(SafetyMonitorInstance.ShutdownInitiated, ArmControlInstance.ReceiveTaskCommand);
end;
